// src/components/MainPage.js
import React from 'react';

const MainPage = () => {
  return (
    <div>
      <h1>Welcome to TriGear</h1>
      <p>Your one-stop resource for triathlon and Ironman gear recommendations.</p>
      <p>
        Whether you're a beginner or an experienced triathlete, our platform
        helps you find the best equipment for every leg of your race.
      </p>
      <div>
        <h2>Why Choose Us?</h2>
        <ul>
          <li>Comprehensive gear reviews</li>
          <li>Expert advice for beginners</li>
          <li>Curated lists of the best equipment</li>
        </ul>
      </div>
      <div>
        <h2>Explore Gear</h2>
        <p>Sign up or log in to explore our full list of products.</p>
      </div>
    </div>
  );
};

export default MainPage;
